/* Terra: Body measurements in Workouts.
   Weight, biceps, waist, chest and body fat, a chart to follow them, and a figure that grows with the numbers:
   the starting point is a dashed outline, today's body is drawn over it. */
const BODY_M = [
  ['weight', 'Weight', 'kg', 30, 250],
  ['biceps', 'Biceps', 'cm', 15, 70],
  ['chest', 'Chest', 'cm', 50, 180],
  ['waist', 'Waist', 'cm', 40, 180],
  ['fat', 'Body fat', '%', 2, 60],
];
const BM = Object.fromEntries(BODY_M.map(([k, l, u, lo, hi]) => [k, { l, u, lo, hi }]));
/* Which way counts as progress, for the colour of the change (weight is the person's own call, so neutral) */
const BODY_GOOD = { biceps: 1, chest: 1, waist: -1, fat: -1, weight: 0 };

const bodyLog = () => (S.body ||= []);
function bodyFirst(k) { return bodyLog().find(e => e[k] != null)?.[k] ?? null; }
function bodyLast(k) { const l = bodyLog(); for (let i = l.length - 1; i >= 0; i--) if (l[i][k] != null) return l[i][k]; return null; }
const fmtN = n => (Math.round(n * 10) / 10).toLocaleString(LOC(), { maximumFractionDigits: 1 });

/* The figure: a calm, front-facing body in the app's style. Each measurement shapes one part,
   and the change since the start is shown a little larger than life so progress is easy to see. */
function bodyShape(f) {
  const sh = 34 * f.chest, wa = 22 * f.waist * (0.9 + 0.1 * f.fat), arm = 7.2 * f.biceps, hip = 25 * Math.max(0.92, f.waist * 0.6 + 0.4);
  const cx = 80, top = 58, wy = 118, hy = 140;
  const torso = `M${cx - sh},${top + 6} C${cx - sh - 2},${top + 30} ${cx - wa - 4},${wy - 18} ${cx - wa},${wy} L${cx - hip},${hy} L${cx + hip},${hy} L${cx + wa},${wy} C${cx + wa + 4},${wy - 18} ${cx + sh + 2},${top + 30} ${cx + sh},${top + 6} C${cx + sh * 0.6},${top - 4} ${cx - sh * 0.6},${top - 4} ${cx - sh},${top + 6} Z`;
  const armPath = side => { const x0 = cx + side * (sh - 3), x1 = cx + side * (sh + 8 + arm * 0.5), y0 = top + 8; return `M${x0},${y0} C${x1},${y0 + 6} ${x1 + side * 2},${y0 + 40} ${x1 - side * 2},${y0 + 70}`; };
  const legs = `M${cx - hip + 3},${hy - 2} L${cx - 9},${hy + 62} M${cx + hip - 3},${hy - 2} L${cx + 9},${hy + 62}`;
  return { torso, armL: armPath(-1), armR: armPath(1), arm, legs, neck: `M${cx},${top - 14} L${cx},${top}` };
}
function bodyFactors(which) {
  const f = {};
  for (const [k] of BODY_M) {
    const a = bodyFirst(k), b = which === 'start' ? a : bodyLast(k);
    const r = a && b ? b / a : 1;
    f[k] = clamp(1 + (r - 1) * 2.4, 0.78, 1.45); // exaggerated a little so a 2 cm change shows
  }
  if (bodyFirst('biceps') == null && bodyFirst('weight') != null) f.biceps = clamp(1 + (f.weight - 1) * 0.6, 0.85, 1.25);
  if (bodyFirst('chest') == null && bodyFirst('weight') != null) f.chest = clamp(1 + (f.weight - 1) * 0.5, 0.85, 1.25);
  if (bodyFirst('waist') == null && bodyFirst('weight') != null) f.waist = clamp(1 + (f.weight - 1) * 0.7, 0.85, 1.25);
  return f;
}
/* The figure is the glowing body outline, warped row by row: the chest band, upper arms, waist and legs
   widen or narrow with the measurements. The starting point is drawn faint underneath, today on top. */
const BODY_PARTS = {"torso": {"src": "data:image/webp;base64,", "x": 474, "y": 47, "w": 327, "h": 375}, "legs": {"src": "data:image/webp;base64,", "x": 506, "y": 446, "w": 293, "h": 522}, "head": {"src": "data:image/webp;base64,", "x": 1245, "y": 606, "w": 200, "h": 276}, "handL": {"src": "data:image/webp;base64,", "x": 880, "y": 554, "w": 109, "h": 176}, "handR": {"src": "data:image/webp;base64,", "x": 1040, "y": 554, "w": 105, "h": 176}};
/* The figure is built from separate body parts (head, torso with arms, hands, legs), placed as on the sheet they come from.
   Each part follows its own measurement: the torso band widens with chest and narrows with waist, the arms thicken with biceps,
   the legs with weight. Coordinates are in the sheet's pixels; the body's centre line is x = 637. */
const BX = 637;
let BODY_IMGS = null;
const kf = (pts, y) => { if (y <= pts[0][0]) return pts[0][1]; for (let i = 1; i < pts.length; i++) if (y <= pts[i][0]) { const [y0, v0] = pts[i - 1], [y1, v1] = pts[i]; return v0 + (v1 - v0) * (y - y0) / (y1 - y0); } return pts.at(-1)[1]; };
function bodyRig(f) {
  const fc = f.chest, fb = f.biceps, fw = f.waist * (1 + (f.fat - 1) * 0.3), fl = 1 + (f.weight - 1) * 0.6;
  return {
    fl,
    Tk: [[47, 400], [150, 400], [195, 82], [250, 80], [300, 86], [340, 92], [368, 95], [422, 95]],
    Fi: [[47, 1], [75, fc], [200, fc], [280, fw], [310, fw], [372, 1.11 * fl]], // the hips flare out to meet the legs
    Fa: [[150, 1], [200, fb], [310, fb], [380, 1 + (fb - 1) * 0.4]],
    Ac: [[200, 113], [300, 128], [400, 137]],
    S: 80 * (fc - 1),
  };
}
/* Where a point dx (from the centre line) on sheet row Y ends up after warping */
function rigX(r, Y, dx) {
  const T = kf(r.Tk, Y), fi = kf(r.Fi, Y);
  if (dx <= T) return dx * fi;
  const fa = kf(r.Fa, Y), ac = kf(r.Ac, Y);
  return T + r.S + (T - ac) * (fa - 1) + (dx - T) * fa;
}
function drawFigure(ctx, f, ox, oy) { // ox, oy: where sheet point (BX, 0) lands on the canvas
  const r = bodyRig(f), I = BODY_IMGS, L = BODY_PARTS;
  // legs, scaled from the centre line
  /* Each part is drawn at the size it has on the reference figure: head 0.66, legs 0.87, hands 0.55 of the sheet size */
  const SL = 0.87, lg = L.legs, lcx = 652.5;
  ctx.drawImage(I.legs, ox + (lg.x - lcx) * SL * r.fl, oy + 364 + (lg.y - 458) * SL, lg.w * SL * r.fl, lg.h * SL);
  // torso, row by row
  const t = L.torso, img = I.torso, cLocal = BX - t.x;
  for (let yy = 0; yy < t.h; yy++) {
    const Y = t.y + yy, T = Math.min(kf(r.Tk, Y), cLocal), fi = kf(r.Fi, Y), dy = oy + Y;
    if (T >= cLocal) { ctx.drawImage(img, 0, yy, t.w, 1, ox - cLocal * fi, dy, t.w * fi, 1); continue; }
    ctx.drawImage(img, cLocal - T, yy, 2 * T, 1, ox - T * fi, dy, 2 * T * fi, 1);
    const fa = kf(r.Fa, Y), start = rigX(r, Y, T + 0.0001), swR = t.w - cLocal - T, swL = cLocal - T;
    ctx.drawImage(img, cLocal + T, yy, swR, 1, ox + start, dy, swR * fa, 1);
    ctx.drawImage(img, 0, yy, swL, 1, ox - start - swL * fa, dy, swL * fa, 1);
  }
  // hands at the (moved) wrists
  const hs = 0.55, wy = 412;
  for (const [k, wx, hx] of [['handL', -137, 922], ['handR', 138, 1102.5]]) {
    const h = L[k], x = Math.sign(wx) * rigX(r, wy, Math.abs(wx)), fb = kf(r.Fa, wy);
    ctx.drawImage(I[k], ox + x - (hx - h.x) * hs * fb, oy + wy - 6 - (566 - h.y) * hs, h.w * hs * fb, h.h * hs);
  }
  // head on the neck
  const hd = L.head;
  const SH = 0.66;
  ctx.drawImage(I.head, ox + (hd.x - 1345) * SH, oy + 72 + (hd.y - 875) * SH, hd.w * SH, hd.h * SH);
}
function drawBody() {
  const cv = document.getElementById('bodyCv'); if (!cv) return;
  const go = () => {
    const ctx = cv.getContext('2d'), many = bodyLog().length > 1, one = { chest: 1, biceps: 1, waist: 1, fat: 1, weight: 1 };
    const ox = cv.width / 2, oy = 150;
    const layer = (f, tint) => {
      const o = document.createElement('canvas'); o.width = cv.width; o.height = cv.height; const x = o.getContext('2d');
      x.fillStyle = '#000'; x.fillRect(0, 0, o.width, o.height); drawFigure(x, f, ox, oy);
      x.globalCompositeOperation = 'multiply'; x.fillStyle = tint; x.fillRect(0, 0, o.width, o.height); return o;
    };
    ctx.globalCompositeOperation = 'source-over'; ctx.fillStyle = '#000'; ctx.fillRect(0, 0, cv.width, cv.height);
    ctx.globalCompositeOperation = 'lighten';
    if (many) { ctx.globalAlpha = 0.5; ctx.drawImage(layer(one, '#b9b4c8'), 0, 0); ctx.globalAlpha = 1; }
    const now = layer(many ? bodyFactors('now') : one, '#7cc4ff');
    ctx.filter = 'blur(7px)'; ctx.drawImage(now, 0, 0); ctx.filter = 'blur(2px)'; ctx.drawImage(now, 0, 0); ctx.filter = 'none'; ctx.drawImage(now, 0, 0);
    ctx.globalCompositeOperation = 'source-over';
  };
  if (BODY_IMGS) { if (BODY_IMGS._ready) go(); else BODY_IMGS._wait.push(go); return; }
  BODY_IMGS = { _ready: false, _wait: [go] }; let left = 5;
  for (const k of Object.keys(BODY_PARTS)) { const im = new Image(); im.onload = () => { if (--left === 0) { BODY_IMGS._ready = true; BODY_IMGS._wait.splice(0).forEach(fn => fn()); } }; im.src = BODY_PARTS[k].src; BODY_IMGS[k] = im; }
}
function bodyFigure() {
  const many = bodyLog().length > 1;
  setTimeout(drawBody, 0);
  return `<div class="body-stage"><canvas id="bodyCv" width="560" height="1000" role="img" aria-label="${many ? 'Your body now, drawn over your starting point' : 'Your starting point'}"></canvas></div>`;
}

/* Line chart for one measurement: the starting value is a dashed line, the newest point is highlighted */
function bodyChart(k) {
  const pts = bodyLog().filter(e => e[k] != null).map(e => ({ d: e.d, v: e[k] }));
  if (pts.length < 2) return `<div class="bc-empty">${pts.length ? 'Add one more measurement to see your line.' : 'No measurements yet.'}</div>`;
  const W = 320, H = 150, pl = 34, pr = 12, pt = 14, pb = 26;
  const vs = pts.map(p => p.v); let lo = Math.min(...vs), hi = Math.max(...vs); const pad = Math.max((hi - lo) * 0.2, 0.5); lo -= pad; hi += pad;
  const t0 = new Date(pts[0].d).getTime(), t1 = new Date(pts.at(-1).d).getTime() || t0 + 1;
  const X = (p, i) => pl + (t1 === t0 ? i / (pts.length - 1) : (new Date(p.d).getTime() - t0) / (t1 - t0)) * (W - pl - pr);
  const Y = v => pt + (1 - (v - lo) / (hi - lo)) * (H - pt - pb);
  const xy = pts.map((p, i) => [X(p, i), Y(p.v)]);
  const line = xy.map(([x, y], i) => `${i ? 'L' : 'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const area = `${line} L${xy.at(-1)[0].toFixed(1)},${H - pb} L${xy[0][0].toFixed(1)},${H - pb} Z`;
  const ticks = [hi - pad, (hi + lo) / 2, lo + pad].map(v => `<text x="${pl - 6}" y="${Y(v) + 4}" text-anchor="end">${fmtN(v)}</text><line x1="${pl}" x2="${W - pr}" y1="${Y(v)}" y2="${Y(v)}" class="bc-grid"/>`).join('');
  const dl = d => new Date(d).toLocaleDateString(LOC(), { day: 'numeric', month: 'numeric' });
  return `<svg class="body-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${BM[k].l} over time">
    <defs><linearGradient id="bcArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".35"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>
    ${ticks}
    <line x1="${pl}" x2="${W - pr}" y1="${Y(pts[0].v)}" y2="${Y(pts[0].v)}" class="bc-start"/>
    <path d="${area}" fill="url(#bcArea)"/><path d="${line}" class="bc-line"/>
    ${xy.map(([x, y], i) => `<circle cx="${x}" cy="${y}" r="${i === xy.length - 1 ? 5 : 3}" class="${i === xy.length - 1 ? 'bc-last' : 'bc-pt'}"/>`).join('')}
    <text x="${pl}" y="${H - 6}" class="bc-x">${dl(pts[0].d)}</text><text x="${W - pr}" y="${H - 6}" text-anchor="end" class="bc-x">${dl(pts.at(-1).d)}</text>
  </svg>`;
}

function secBody() {
  const log = bodyLog();
  const sel = BM[S.bodyMetric] ? S.bodyMetric : (BODY_M.find(([k]) => bodyLog().filter(e => e[k] != null).length > 1)?.[0] || 'weight');
  if (!log.length) {
    return `<section class="card body-card body-empty"><div class="body-empty-in"><div><p class="eyebrow">Body</p><h2 class="h2">Track your measurements</h2>
      <p class="small">Weight, biceps, waist, chest and body fat. Your figure grows with your results, drawn over your starting point.</p>
      <button class="btn primary" type="button" data-act="bodyAdd">${IC.plus} Add your starting point</button></div>${bodyFigure()}</div></section>`;
  }
  const chips = BODY_M.map(([k, l, u]) => {
    const a = bodyFirst(k), b = bodyLast(k); if (b == null) return '';
    const d = a != null ? b - a : 0, g = BODY_GOOD[k], tone = !d || !g ? '' : (d * g > 0 ? 'up' : 'down');
    return `<button class="bm-chip ${k === sel ? 'on' : ''}" type="button" data-act="bodyMetric" data-k="${k}"><small>${l}</small><b class="tnum">${fmtN(b)}<i>${u}</i></b>${log.length > 1 ? `<span class="bm-d ${tone}">${d > 0 ? '+' : d < 0 ? '−' : '±'}${fmtN(Math.abs(d))}</span>` : ''}</button>`;
  }).join('');
  const recent = [...log].reverse().slice(0, 4);
  return `<section class="card body-card">
      <div class="section-head"><div><p class="eyebrow">Body</p><h2 class="h2">Your progress</h2></div><button class="pill-add wide" type="button" data-act="bodyAdd">${IC.plus}<span>Add</span></button></div>
      <div class="body-top">${bodyFigure()}<div class="bf-legend">${log.length > 1 ? `<span><i class="lg-now"></i>Now</span><span><i class="lg-start"></i>${tr('Starting point')} · ${fmtDay(log[0].d)}</span>` : `<span><i class="lg-now"></i>Starting point</span><span class="small">Add new measurements in a week or two and watch the figure change.</span>`}</div></div>
      <div class="bm-chips">${chips}</div>
      <div class="bc-wrap"><p class="small bc-title">${tr(BM[sel].l)} (${BM[sel].u})</p>${bodyChart(sel)}</div>
      <div class="list body-hist">${recent.map(e => `<div class="item"><div class="txt"><b>${fmtDay(e.d)}</b><small>${BODY_M.filter(([k]) => e[k] != null).map(([k, l, u]) => `${l} ${fmtN(e[k])} ${u}`).join(' · ')}</small></div><button class="icon-btn" type="button" data-act="bodyDel" data-id="${e.id}" aria-label="Delete measurement">${IC.close}</button></div>`).join('')}</div>
    </section>`;
}

function bodySheet() {
  openSheet(`<div class="sheet-head"><h2 class="h2">Add measurements</h2><button class="icon-btn" type="button" data-sheet-close aria-label="Close">${IC.close}</button></div>
    <p class="small" style="margin:0">Fill in what you measured. Everything is optional.</p>
    <form class="stack" data-form="body">
      <div class="bm-grid">${BODY_M.map(([k, l, u, lo, hi]) => { const last = bodyLast(k); return `<label class="field bm-in"><span>${l}</span><span class="bm-box"><input type="text" inputmode="decimal" name="${k}" placeholder="${last != null ? fmtN(last) : '–'}" autocomplete="off"><i>${u}</i></span></label>`; }).join('')}</div>
      <p class="small step-warn" id="bmWarn" hidden>Add at least one measurement.</p>
      <div class="sheet-btns"><button class="btn ghost" type="button" data-sheet-close>Cancel</button><button class="btn primary" type="submit">Save</button></div>
    </form>`, b => b.querySelectorAll('[data-sheet-close]').forEach(x => x.addEventListener('click', closeSheet)));
}

document.addEventListener('click', e => {
  const a = e.target.closest('[data-act]'); if (!a || a.disabled) return;
  const act = a.dataset.act;
  if (act === 'bodyAdd') bodySheet();
  if (act === 'bodyMetric') { S.bodyMetric = a.dataset.k; save(); render(); }
  if (act === 'bodyDel') { const i = bodyLog().findIndex(x => x.id === a.dataset.id); if (i >= 0) { bodyLog().splice(i, 1); save(); render(); toast('Measurement deleted'); } }
});
document.addEventListener('submit', e => {
  const f = e.target; if (f.dataset.form !== 'body') return;
  e.preventDefault();
  const rec = { id: uid(), d: dayKey() };
  for (const [k, , , lo, hi] of BODY_M) {
    const v = parseFloat(String(f.elements[k].value || '').replace(',', '.'));
    if (Number.isFinite(v) && v >= lo && v <= hi) rec[k] = Math.round(v * 10) / 10;
  }
  if (Object.keys(rec).length <= 2) { f.querySelector('#bmWarn').hidden = false; return; }
  const log = bodyLog(); const same = log.findIndex(x => x.d === rec.d);
  if (same >= 0) log[same] = { ...log[same], ...rec, id: log[same].id }; else log.push(rec); // one entry per day, the newest numbers win
  log.sort((x, y) => x.d.localeCompare(y.d));
  S.bodyMetric = BODY_M.find(([k]) => rec[k] != null)[0];
  save(); closeSheet(); render(); toast(log.length > 1 ? 'Measurements saved. Look at that figure!' : 'Starting point saved');
});
